CREATE TABLE "orchestrator_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "case_id" bigint NOT NULL,
  "trigger_type" varchar(30) NOT NULL,
  "trigger_key" varchar(255) NOT NULL,
  "orchestrator_runs_status" varchar(20) NOT NULL DEFAULT 'PENDING',
  "next_action" varchar(50),
  "result_data" jsonb,
  "error_message" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "completed_at" timestamptz
);

CREATE TABLE "policy_rag_results" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "clauses" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "reviews" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "evidence_gaps" text,
  CONSTRAINT "policy_rag_results_clauses_array_check"
    CHECK (jsonb_typeof(clauses) = 'array'),
  CONSTRAINT "policy_rag_results_reviews_array_check"
    CHECK (jsonb_typeof(reviews) = 'array')
);

CREATE TABLE "policy_vector_store" (
  "id" uuid PRIMARY KEY,
  "content" text NOT NULL,
  "metadata" jsonb NOT NULL,
  "embedding" vector NOT NULL
);

COMMENT ON TABLE "policy_rag_results" IS '독립 RAG 결과. orchestrator_runs.result_data의 policyRagResultId로 참조한다.';
COMMENT ON COLUMN "policy_rag_results"."clauses" IS '검색된 정책 발췌. 각 항목은 chunkId, policyName, articleTitle, articleNumber, originalTextEn, officialUrl을 담는다.';
COMMENT ON COLUMN "policy_rag_results"."reviews" IS '조항별 검토. 각 항목은 chunkId, applicability, reason, missingInformation을 담는다.';
COMMENT ON COLUMN "policy_rag_results"."evidence_gaps" IS '사건에서 추가로 확인할 거래 사실이나 준비할 증빙에 대한 보완 노트.';
COMMENT ON COLUMN "policy_vector_store"."metadata" IS '필수 키는 platform, site, sourceUrl, policyTitle, updatedAt이다. updatedAt은 마지막 정상 적재 시각이다.';

